/** Conversions between the application models and the "customers" table: what the service takes and returns. */
import type { CustomerForm, CustomerState } from '../application-models.js'
import type { CustomerCreate, CustomerRead } from '../dtos/customer.js'

/** The value an enum pair gives, or the fallback; a value without a pair is an error. */
function pair(pairs: Record<string, string>, value: unknown, fallback?: string): string {
  const found = pairs[String(value)] ?? fallback
  if (found === undefined) throw new Error(`No pair for ${String(value)}`)
  return found
}

/** A CustomerForm as the customers table takes it. */
export function customerFormToCustomerCreate(model: CustomerForm): CustomerCreate {
  return {
    email: model.email,
    fullName: [model.firstName, model.lastName].map(String).join(' '),
    status: pair({ 'ACTIVE': 'active', 'BLOCKED': 'blocked' }, model.status),
    createdAt: new Date(Number(model.signedUp) * 1000),
    balanceCents: Math.round((Number(model.balance) * 100)),
    // TODO: nickname: the matching waits for review (nickname)
    nickname: undefined as never,
    // TODO: country: no field of the model gives it
    country: undefined as never,
  }
}

/** A row of the customers table as a CustomerForm. */
export function customerReadToCustomerForm(row: CustomerRead): CustomerForm {
  return {
    email: row.email,
    // TODO: firstName: Mapper's relation only goes the other way (firstName, lastName)
    firstName: undefined as never,
    // TODO: lastName: Mapper's relation only goes the other way (firstName, lastName)
    lastName: undefined as never,
    status: (pair({ 'active': 'ACTIVE', 'blocked': 'BLOCKED' }, row.status) as CustomerState),
    signedUp: Math.round(row.createdAt.getTime() / 1000),
    balance: (Number(row.balanceCents) / 100),
    // TODO: nickname: the matching waits for review (nickname)
    nickname: undefined as never,
  }
}

