/** Repository of the "customers" table: reads and writes rows, and decides nothing. */
import { asc, count, eq } from 'drizzle-orm'
import { isRefusal, type Executor } from '../database.js'
import { Customer } from '../entities/customer.js'
import { ConflictError } from '../errors.js'
import type { Page } from '../paging.js'
import { customers } from '../schema.js'

/** Where customers rows are kept. Services depend only on this interface. */
export interface CustomerRepository {
  findById(id: number): Promise<Customer | null>
  list(offset?: number, limit?: number): Promise<Page<Customer>>
  findByEmail(email: string): Promise<Customer | null>
  insert(entity: Customer): Promise<Customer>
  update(entity: Customer): Promise<Customer>
  delete(entity: Customer): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Customer): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The Customer of a row Drizzle read. */
function toEntity(row: typeof customers.$inferSelect): Customer {
  return Object.assign(new Customer(), row)
}

/** The values of a new row; those left undefined take the database's default. */
function insertValues(entity: Customer): typeof customers.$inferInsert {
  return {
    id: entity.id,
    email: entity.email,
    fullName: entity.fullName,
    status: entity.status,
    createdAt: entity.createdAt,
    balanceCents: entity.balanceCents,
    nickname: entity.nickname,
    country: entity.country,
  }
}

/** The values a change writes: not the key, nor what the database fills. */
function updateValues(entity: Customer): Partial<typeof customers.$inferInsert> {
  return {
    email: entity.email,
    fullName: entity.fullName,
    status: entity.status,
    createdAt: entity.createdAt,
    balanceCents: entity.balanceCents,
    nickname: entity.nickname,
    country: entity.country,
  }
}

/** Keeps customers rows in the database, through Drizzle. It never commits: the transaction belongs to the database it was given. */
export class SqlCustomerRepository implements CustomerRepository {
  constructor(private readonly db: Executor) {}

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Customer | null> {
    const [row] = await this.db.select().from(customers).where(eq(customers.id, id)).limit(1)
    return row === undefined ? null : toEntity(row)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Customer>> {
    const rows = await this.db.select().from(customers).orderBy(asc(customers.id)).limit(limit).offset(offset)
    const [{ total }] = await this.db.select({ total: count() }).from(customers)
    return { items: rows.map(toEntity), total, offset, limit }
  }

  /** The row with this email, or null. */
  async findByEmail(email: string): Promise<Customer | null> {
    const [row] = await this.db.select().from(customers).where(eq(customers.email, email)).limit(1)
    return row === undefined ? null : toEntity(row)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Customer): Promise<Customer> {
    try {
      const [ids] = await this.db.insert(customers).values(insertValues(entity)).$returningId()
      Object.assign(entity, ids)
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('Customer', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
    const [row] = await this.db.select().from(customers).where(eq(customers.id, entity.id)).limit(1)
    return row === undefined ? entity : Object.assign(entity, toEntity(row))
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Customer): Promise<Customer> {
    try {
      await this.db.update(customers).set(updateValues(entity)).where(eq(customers.id, entity.id))
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('Customer', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Customer): Promise<void> {
    try {
      await this.db.delete(customers).where(eq(customers.id, entity.id))
    } catch (error) {
      if (isRefusal(error)) throw new ConflictError('Customer', `the database refused the change: ${(error as Error).message}`)
      throw error
    }
  }
}

/** Keeps customers rows in memory, for tests and for trying the services without a database. */
export class MemoryCustomerRepository implements CustomerRepository {
  private readonly rows = new Map<string, Customer>()
  private nextId = 1

  private visible(): Customer[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Customer | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Customer>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** The row with this email, or null. */
  async findByEmail(email: string): Promise<Customer | null> {
    return this.visible().find((row) => row.email === email) ?? null
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Customer): Promise<Customer> {
    if (entity.id === undefined) entity.id = this.nextId++
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Customer): Promise<Customer> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Customer): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }
}

