/** The tables of the database, as Drizzle reads and writes them. They reflect the database: do not migrate with them. */
import { sql } from 'drizzle-orm'
import { char, check, datetime, int, mysqlTable, unique, varchar } from 'drizzle-orm/mysql-core'

/** The "customers" table. */
export const customers = mysqlTable(
  'customers',
  {
    id: int('id').primaryKey().autoincrement(),
    email: varchar('email', { length: 120 }).notNull(),
    fullName: varchar('full_name', { length: 120 }).notNull(),
    status: varchar('status', { length: 10 }).notNull(),
    createdAt: datetime('created_at', { mode: 'date' }).notNull(),
    balanceCents: int('balance_cents').notNull(),
    nickname: varchar('nickname', { length: 40 }),
    country: char('country', { length: 2 }).notNull(),
  },
  (t) => [
    unique().on(t.email),
    check('customers_check_1', sql.raw('status IN (\'active\', \'blocked\')')),
  ],
)

