/** Tests of the "customers" table. */
import { describe, expect, it } from 'vitest'
import type { CustomerCreate } from '../src/dtos/customer.js'
import { ConflictError, NotFoundError, ValidationFailedError } from '../src/errors.js'
import { CustomerService } from '../src/services/customer.js'
import { MemoryUnitOfWork } from '../src/unit-of-work.js'
import { useTestDatabase } from './database.js'
import { addCustomer, newCustomer } from './factories.js'

/** The repositories over the test database, opened empty for every test */
const sqlUow = useTestDatabase()

describe('customers repository', () => {
  it('is stored and read back', async () => {
    const uow = sqlUow()
    const stored = await addCustomer(uow, 1)
    const found = await uow.customers.findById(stored.id)
    expect(found).not.toBeNull()
    expect(found!.id).toEqual(stored.id)
    expect(await uow.customers.findByEmail(stored.email)).not.toBeNull()
  })

  it('lists rows by key', async () => {
    const uow = sqlUow()
    await addCustomer(uow, 1)
    await addCustomer(uow, 2)
    const page = await uow.customers.list(0, 1)
    expect(page.total).toBe(2)
    expect(page.items).toHaveLength(1)
  })

  it('stores the changes', async () => {
    const uow = sqlUow()
    const stored = await addCustomer(uow, 1)
    stored.fullName = 'changed'
    await uow.customers.update(stored)
    const found = await uow.customers.findById(stored.id)
    expect(found?.fullName).toBe('changed')
  })

  it('is deleted', async () => {
    const uow = sqlUow()
    const stored = await addCustomer(uow, 1)
    await uow.customers.delete(stored)
    expect(await uow.customers.findById(stored.id)).toBeNull()
  })
})

describe('CustomerService', () => {
  it('creates a valid row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const created = await service.createCustomer(pick<CustomerCreate>(newCustomer(1), CREATE_FIELDS))
    const found = await service.getCustomer(created.id)
    expect(found.id).toEqual(created.id)
  })

  it('refuses a missing value', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const error: unknown = await service.createCustomer({ ...pick<CustomerCreate>(newCustomer(1), CREATE_FIELDS), email: null } as unknown as CustomerCreate).catch((caught: unknown) => caught)
    expect(error).toBeInstanceOf(ValidationFailedError)
    expect((error as ValidationFailedError).errors.map((item) => item.field)).toEqual(['email'])
  })

  it('refuses a repeated unique value', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const first = await service.createCustomer(pick<CustomerCreate>(newCustomer(1), CREATE_FIELDS))
    await expect(service.createCustomer(pick<CustomerCreate>(newCustomer(2, { email: first.email }), CREATE_FIELDS))).rejects.toBeInstanceOf(ConflictError)
  })

  it('keeps its own unique value', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const created = await service.createCustomer(pick<CustomerCreate>(newCustomer(1), CREATE_FIELDS))
    await service.updateCustomer(created.id, { email: created.email })
  })

  it('says when a row is missing', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    await expect(service.getCustomer(999999)).rejects.toBeInstanceOf(NotFoundError)
  })

  it('changes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const created = await service.createCustomer(pick<CustomerCreate>(newCustomer(1), CREATE_FIELDS))
    const updated = await service.updateCustomer(created.id, { fullName: 'changed' })
    expect(updated.fullName).toBe('changed')
  })

  it('deletes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new CustomerService(uow)
    const n = 100
    const created = await service.createCustomer(pick<CustomerCreate>(newCustomer(1), CREATE_FIELDS))
    await service.deleteCustomer(created.id)
    await expect(service.getCustomer(created.id)).rejects.toBeInstanceOf(NotFoundError)
  })
})

/** Fields of the create DTO */
const CREATE_FIELDS = ['email', 'fullName', 'status', 'createdAt', 'balanceCents', 'nickname', 'country']

/** The values a DTO takes, from a row the factories made. */
function pick<T>(row: object, fields: readonly string[]): T {
  return Object.fromEntries(Object.entries(row).filter(([name]) => fields.includes(name))) as T
}

